<?php
namespace App\Http\Controllers;
use App\Models\Employee;use App\Models\PayrollCell;use App\Models\PayrollPeriod;use App\Models\PayrollRow;use App\Models\PayrollSheet;use App\Models\Project;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use PhpOffice\PhpSpreadsheet\IOFactory;
class PayrollImportController extends Controller {
 public function store(Request $r,PayrollPeriod $period){abort_if($period->published_at,422,'پس از انتشار دوره، بارگذاری مجدد پرسنل مجاز نیست.');abort_if($period->isEditingExpired(),422,'مهلت این دوره پایان یافته است.');$d=$r->validate(['file'=>'required|file|mimes:xlsx,xls,csv|max:10240']);$sheet=IOFactory::load($d['file']->getRealPath())->getActiveSheet();$rows=$sheet->toArray(null,true,true,false);if(count($rows)<2)return back()->withErrors(['file'=>'فایل فاقد داده است.']);$headers=array_map(fn($v)=>trim((string)$v),array_shift($rows));$aliases=['نام'=>'first_name','نام خانوادگی'=>'last_name','شماره پرسنلی'=>'personnel_number','کد ملی'=>'national_id','پروژه'=>'project'];$map=[];foreach($headers as $i=>$h)if(isset($aliases[$h]))$map[$aliases[$h]]=$i;foreach(array_keys($aliases) as $fa){$key=$aliases[$fa];if(!isset($map[$key]))return back()->withErrors(['file'=>"ستون «{$fa}» یافت نشد."]);}
  DB::transaction(function()use($rows,$map,$r,$period){$projects=Project::active()->get();foreach($rows as $idx=>$row){if(!array_filter($row,fn($v)=>$v!==null&&$v!==''))continue;$projectName=trim((string)$row[$map['project']]);$project=$projects->first(fn($p)=>$p->name===$projectName||$p->code===$projectName);if(!$project)throw \Illuminate\Validation\ValidationException::withMessages(['file'=>'پروژه ناشناخته در ردیف '.($idx+2).': '.$projectName]);$emp=Employee::updateOrCreate(['personnel_number'=>(string)$row[$map['personnel_number']]],['national_id'=>(string)$row[$map['national_id']],'first_name'=>(string)$row[$map['first_name']],'last_name'=>(string)$row[$map['last_name']],'default_project_id'=>$project->id,'is_active'=>true]);$ps=PayrollSheet::firstOrCreate(['period_id'=>$period->id,'project_id'=>$project->id],['project_name_snapshot'=>$project->name]);PayrollRow::updateOrCreate(['period_id'=>$period->id,'employee_id'=>$emp->id],['sheet_id'=>$ps->id,'first_name_snapshot'=>$emp->first_name,'last_name_snapshot'=>$emp->last_name,'personnel_number_snapshot'=>$emp->personnel_number,'national_id_snapshot'=>$emp->national_id,'sort_order'=>$idx+1,'created_by'=>$r->user()->id]);}});return back()->with('status','فهرست پرسنل با موفقیت بارگذاری شد.');}
}
